/// <summary>
///
/// </summary>
public display NoYesId displayIsHazardousMaterial()
{
    SalesLine           salesLine;
    HMIMItemMaterial    hmimItemMaterial;

    //return NoYes::Yes;

    select firstonly RecId from hmimItemMaterial
        exists join salesLine
            where salesline.ItemId == hmimItemMaterial.ItemId       &&
                salesLine.SalesId == this.OrderNum;

    if (hmimItemMaterial.RecId != 0)
    {
        return NoYes::Yes;
    }
    else
    {
        return NoYes::No;
    }
}

/// <summary>
/// Method used in sales finalization because of group by on order num
/// </summary>
/// <returns></returns>
public display SalesStatus displaySalesStatus()
{
    return SalesLine::find(this.OrderNum, this.LineNum).SalesStatus;
}

public display METOrderExtractStatus displayOrderExtractStatus()
{
    return SalesLine::find(this.OrderNum, this.LineNum).metSalesLine().OrderExtractStatus;
}

